    <label class="grid md:grid-cols-[220px_1fr] items-center gap-3"><span>Nombre de usuario</span><input class="bg-slate-800 border border-slate-700 p-3 rounded" name="name" pattern="[A-Za-z0-9._-]{3,120}" maxlength="120" autocomplete="username" required></label>
