 <section id="manejar-usuarios" class="scroll-mt-24"><h2 class="text-xl font-bold mb-3">Manejar usuarios</h2><div class="overflow-auto border border-slate-800 rounded-xl"><table class="w-full"><thead class="bg-slate-900 text-left text-slate-400"><tr><th class="p-3">ID</th><th>Nombre</th><th>Correo</th><th>Grupo</th><th>Estado</th><th class="p-3 text-right">Control</th></tr></thead><tbody><?php foreach($users as $u):?><tr class="border-t border-slate-800"><td class="p-3"><?=$u['id']?></td><td><?=htmlspecialchars($u['name'])?></td><td><?=$u['email']?htmlspecialchars($u['email']):'<span class="text-slate-500">Sin correo</span>'?></td><td><?=htmlspecialchars($u['group_names']?:'Sin grupo')?></td><td><?=htmlspecialchars($u['status'])?></td><td class="p-3"><div class="flex justify-end"><?php if($u['id']!==\App\Security\Auth::id()):?><form method="post" action="/users/status" onsubmit="return confirm('¿Cambiar el acceso de este usuario administrativo?')"><?=$csrf->field()?><input type="hidden" name="id" value="<?=$u['id']?>"><input type="hidden" name="status" value="<?=$u['status']==='blocked'?'active':'blocked'?>"><button class="<?=$u['status']==='blocked'?'bg-blue-700':'bg-red-800'?> px-3 py-1 rounded"><?=$u['status']==='blocked'?'Activar':'Bloquear usuario'?></button></form><?php else:?><span class="text-xs text-slate-500">Sesión actual</span><?php endif?></div></td></tr><?php endforeach?></tbody></table></div></section>
